(function(){
  'use strict';
  const M=window.CareBridge,U=window.CareBridgeUX,KEY='carebridge-prototype-v2';
  let agentError='',basicMode=false,sourceEditMode=false;
  const roles={hospital:'의뢰기관',patient:'환자·보호자',facility:'수용기관',simulation:'시연 시스템'};
  let state=M.initial(),role='hospital',view='case',facility='saebom',compare=new Set(),toastTimer,consentDraft=false;
  let apiReady=false,aiAvailable=false,apiChecked=false,working=false,autoEnabled=true,autoRunning=false,autoRunId=0,generation=0,apiCalls=[],routeResults={},hospitalResults=null,hospitalFocus=null,hospitalArea='gwanak',hospitalLoading=false,hospitalError='',aiError='',liveMessage='서비스 준비 중';
  try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Number.isInteger(saved.stage)&&saved.stage>=0&&saved.stage<=7)state=saved;}catch{}
  if(!state.preferences.profile)state.preferences.profile='balanced';state.facilityUpdates=state.facilityUpdates||{};state.agentRuns=state.agentRuns||[];state.inquiryDraft=state.inquiryDraft||'';
  try{autoEnabled=localStorage.getItem(KEY+'-auto')!=='false';}catch{}
  const $=s=>document.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>n.toLocaleString('ko-KR')+'원';
  const serviceText=value=>String(value??'').replace(/Gemini/g,'AI').replace(/기관 시연 API/g,'기관').replace(/기관 API/g,'기관').replace(/AI API/g,'AI').replace(/실제 API/g,'실제').replace(/API/g,'서비스');
  const displayFact=value=>esc(serviceText(value).replace(/\s*\((?:가상(?:·비교용)?|시연(?: 기준)?)\)/g,''));
  const facilityType=f=>esc(f.type.replace(/^가상\s+/,''));
  const when=t=>new Date(t).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
  const button=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
  const badge=(text,tone='')=>`<span class="badge ${tone}">${text}</span>`;
  const statusBadge=x=>badge(`<span aria-hidden="true" class="status-symbol">${esc(x.icon)}</span>${esc(x.label)}`,x.tone+' status-badge');
  const capability=(label,yes)=>statusBadge({label:label+(yes?' 가능':' 불가'),tone:yes?'green':'red',icon:yes?'✓':'×'});
  const checks=(key,text,checked,more='')=>`<label class="check"><input type="checkbox" data-change="${key}" ${checked?'checked':''}><span>${text}${more?`<small>${more}</small>`:''}</span></label>`;
  const dl=(items)=>`<dl>${items.map(([k,v])=>`<div class="data-row"><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  const selected=()=>M.facilities.find(f=>f.id===state.selected);
  function toast(message,error=false){if(error&&$('#dialog').open){let alert=$('#dialog .dialog-error');if(!alert){alert=document.createElement('p');alert.className='notice red dialog-error';alert.setAttribute('role','alert');$('#dialog .dialog-body').prepend(alert);}alert.textContent=serviceText(message);alert.scrollIntoView({block:'nearest'});}const t=$('#toast');t.textContent=serviceText(message);t.className='show'+(error?' toast-error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',4000);}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-auto',String(autoEnabled));}catch{toast('이 브라우저에서는 진행 상태를 저장할 수 없습니다.');}}
  function setBusy(value,label='진행 상태를 반영하고 있습니다…'){
    working=value;document.body.classList.toggle('is-working',value);document.body.setAttribute('aria-busy',String(value));
    if(value){for(const el of document.querySelectorAll('button,input,select,textarea')){if(el.disabled||el.dataset.action==='close'||el.dataset.action==='toggle-auto')continue;el.dataset.busyDisabled='true';el.disabled=true;}let status=document.querySelector('#busy-status');if(!status){status=document.createElement('div');status.id='busy-status';status.setAttribute('role','status');document.body.append(status);}status.textContent=label;}
    else{for(const el of document.querySelectorAll('[data-busy-disabled]')){el.disabled=false;delete el.dataset.busyDisabled;}document.querySelector('#busy-status')?.remove();}
  }
  async function analyzeAI(){
    if(working)return;if(!state.doctorApproved){toast('담당의의 비응급 회송 결정을 먼저 확인해 주세요.',true);return;}
    if(state.source!==M.initial(state.scenario).source){toast('AI는 준비된 예시 회송서만 분석합니다. 편집한 문서는 기본 항목 점검을 사용해 주세요.',true);return;}
    const epoch=generation;aiError='';setBusy(true,'AI가 가상 회송서를 분석하고 원문과 대조하고 있습니다…');
    try{const start=performance.now(),r=await fetch('/api/extract?scenario='+state.scenario,{signal:AbortSignal.timeout(25000)}),result=await r.json();result.cached=!!result.cached||['HIT','STALE'].includes(r.headers.get('x-vercel-cache'))||Number(r.headers.get('age'))>0;apiCalls.unshift({action:'AI 문서 추출',status:r.status,ms:Math.round(performance.now()-start),time:new Date().toISOString()});if(!r.ok)throw Error(result.error);if(epoch!==generation)return;setBusy(false);if(await act({type:'applyExtraction',result}))toast('AI 분석과 원문 대조를 완료했습니다.');}
    catch(e){if(epoch===generation){aiError=e.message||'AI 분석을 잠시 후 다시 시도해 주세요.';setBusy(false);render();toast('AI 분석을 완료하지 못했습니다. 기본 항목 점검으로 계속할 수 있습니다.',true);}}finally{setBusy(false);}
  }
  async function act(action,actor=role){
    if(working){toast('앞선 요청을 처리하고 있습니다. 잠시 후 다시 시도해 주세요.');return false;}
    setBusy(true);const epoch=generation;
    try{let next;const started=performance.now();
      if(apiReady){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),9000);try{const response=await fetch('/api/transition',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state,action,actor}),signal:controller.signal});const result=await response.json();apiCalls.unshift({action:action.type,status:response.status,ms:Math.round(performance.now()-started),time:new Date().toISOString()});apiCalls=apiCalls.slice(0,40);if(!response.ok)throw Error(result.error);next=result.state;}finally{clearTimeout(timeout);}}
      else{next=M.transition(state,action,actor);}
      if(epoch!==generation)return false;const stageChanged=state.stage!==next.stage;state=next;save();working=false;render();if(stageChanged){$('.page-heading')?.scrollIntoView({block:'start',behavior:'smooth'});$('#task-title')?.focus({preventScroll:true});}queueMicrotask(kickAutomation);return true;
    }catch(e){if(epoch===generation){state.metrics.errors++;save();toast(e.name==='AbortError'?'처리 시간이 초과되었습니다. 진행 상태는 유지했습니다.':e.message||'작업을 완료하지 못했습니다.',true);}return false;}
    finally{setBusy(false);}
  }
  async function runAgent(){
    if(working)return false;const epoch=generation;agentError='';setBusy(true,'AI가 환자 조건과 기관 회신을 확인하고 있습니다…');
    try{const start=performance.now(),r=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state}),signal:AbortSignal.timeout(27000)}),result=await r.json();apiCalls.unshift({action:'Gemini 매칭·업무 판단',status:r.status,ms:Math.round(performance.now()-start),time:new Date().toISOString()});if(!r.ok)throw Error(result.error||'AI 업무 판단에 실패했습니다.');if(epoch!==generation)return false;setBusy(false);return await act({type:'recordAgent',result},'hospital');}
    catch(e){if(epoch===generation){agentError=e.name==='TimeoutError'?'AI 응답 시간이 초과되었습니다. 다시 시도할 수 있습니다.':e.message;setBusy(false);render();toast('AI 업무 판단을 완료하지 못해 자동 진행을 멈췄습니다.',true);}return false;}finally{setBusy(false);}
  }
  async function facilityReceipt(id,snapshot){
    for(let attempt=0;attempt<2;attempt++){
      try{
        const start=performance.now(),r=await fetch('/api/facility',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:M.facilityRequest(snapshot,id)}),signal:AbortSignal.timeout(6000)}),result=await r.json();
        apiCalls.unshift({action:M.facilities.find(f=>f.id===id).name+' 기관 시연 API',status:r.status,ms:Math.round(performance.now()-start),time:new Date().toISOString()});
        if(r.ok)return {id,receipt:result.receipt};
        if(r.status>=400&&r.status<500)return {id,requestError:true,message:result.error||'문의 요약의 형식을 확인해 주세요.'};
        if(attempt===1)return {id,requestError:true,message:'기관 문의를 완료하지 못했습니다. 다시 시도해 주세요.'};
      }catch(e){if(attempt===1)return e.name==='TimeoutError'||e.name==='AbortError'?{id,error:true}:{id,requestError:true,message:'기관 문의 통신을 완료하지 못했습니다. 다시 시도해 주세요.'};}
    }
  }
  async function kickAutomation(){
    if(!autoEnabled||autoRunning||working||!apiChecked)return;
    if(!(state.stage===1&&state.consent||state.stage===2&&state.consent))return;
    if(agentError)return;
    autoRunning=true;const epoch=generation,runId=++autoRunId;
    try{
      if(state.stage===1){
        liveMessage=basicMode?'기본 시연 · 코드 조건 점검 후 문의 생성':'Matching Agent · 환자 조건과 기관 근거 분석';render();
        if(!basicMode&&!await runAgent())return;
        if(!autoEnabled||epoch!==generation||!state.consent||state.stage!==1)return;
        if(!basicMode&&state.lastAgent?.nextAction!=='send_inquiries'){liveMessage='조건에 맞는 기관 없음 · 담당자 예외 처리 필요';render();return;}
        if(!await act({type:'send'},'hospital'))return;
      }
      const round=state.round,pending=state.inquiries.filter(id=>!state.responses[id]);
      if(pending.length){
        const inquiryReady=state.inquiryDraft&&['treatment','period','isolation'].every(k=>state.inquiryDraft.includes(M.fields[k]+': '+state.data[k]));
        if(!basicMode&&!inquiryReady){liveMessage='문의 초안을 작성·검증한 뒤 기관에 전달합니다.';render();if(!await runAgent())return;}
        if(!autoEnabled||epoch!==generation||state.stage!==2||!state.consent)return;
        liveMessage=pending.length+'개 기관의 수용 여부를 확인하고 있습니다.';render();
        if(basicMode){for(const id of pending){if(!autoEnabled||epoch!==generation||state.stage!==2)return;await act({type:'demoResponse',id},'simulation');}}
        else{
          const results=await Promise.all(pending.map(id=>facilityReceipt(id,JSON.parse(JSON.stringify(state)))));
          for(const result of results){if(!autoEnabled||epoch!==generation||state.stage!==2||!state.consent||state.round!==round)return;if(state.responses[result.id]||result.requestError)continue;await act(result.error?{type:'timeout',id:result.id}:{type:'receipt',receipt:result.receipt},'simulation');}
          const failed=results.find(r=>r.requestError);if(failed){agentError=M.facilities.find(f=>f.id===failed.id).name+': '+failed.message;liveMessage='기관 문의 요청 확인 필요 · 무응답으로 처리하지 않았습니다.';render();return;}
        }
      }
      if(!autoEnabled||epoch!==generation||state.stage!==2||!state.consent)return;
      if(!basicMode){liveMessage='AI가 기관 회신을 분석하고 다음 작업을 확인합니다.';render();if(!await runAgent())return;}
      if(autoEnabled&&epoch===generation&&state.stage===2&&M.accepted(state).length&&(basicMode||state.lastAgent?.nextAction==='present_candidates')){liveMessage='수용 확인된 후보 공개 · 환자 선택 대기';await act({type:'publish'},'hospital');toast('기관 회신과 추천 근거를 비교 화면에 반영했습니다.');}
      else if(state.stage===2){liveMessage='기관 회신 분석 완료 · 보완 요청 또는 재탐색이 필요합니다.';render();}
    }finally{if(runId===autoRunId)autoRunning=false;}
  }
  function allAnsweredWithoutAcceptance(){return state.stage===2&&state.inquiries.length>0&&state.inquiries.every(id=>state.responses[id])&&!M.accepted(state).length;}
  function nextRole(){return state.stage===0?'hospital':state.stage===1&&!state.consent?'patient':state.stage===2?(allAnsweredWithoutAcceptance()?'hospital':'facility'):state.stage===3?'patient':state.stage===5?'facility':'hospital';}
  function connectionPanel(){const status=state.stage>=3?['환자 선택 대기 · 자동으로 기관을 선택하지 않습니다.','의뢰기관의 서류·일정·안내 확인 대기','수용기관의 첫 진료 회신 대기','의뢰기관 최종 확인 대기','첫 진료 이행과 의뢰기관 확인 완료'][state.stage-3]:liveMessage;return `<section class="panel automation-panel"><div class="row space"><div><h2>AI 연계 진행</h2><p class="tiny">조건 매칭 → 동시 문의 → 회신 분석 → 후보 안내</p></div>${button(autoEnabled?'자동 진행 켜짐':'자동 진행 꺼짐','toggle-auto',autoEnabled?'selected small':'small',`aria-pressed="${autoEnabled}"`)}</div><div class="automation-live" role="status"><span class="connection-dot ${autoEnabled?'on':''}"></span>${esc(autoEnabled?status:'자동 진행 일시 정지 · 각 역할 화면에서 직접 처리')}</div><div class="integration-pills">${badge(apiReady?'서비스 이용 가능':'기본 시연 모드',apiReady?'green':'amber')}${badge('기관 응답은 모의 데이터')}</div>${state.lastAgent?`<div class="agent-result"><b>${esc(state.lastAgent.actionLabel)}</b><p>AI 분석 완료${state.lastAgent.cached?' · 검증 결과 재사용':''}</p>${button('추천 근거·문의·회신 보기','agent-detail','small')}</div>`:''}${agentError?`<div class="notice amber" role="alert">${esc(serviceText(agentError))}<div class="row">${button('AI 다시 시도','retry-agent','small')}${button('기본 시연으로 계속','basic-demo','small')}</div></div>`:''}${basicMode?'<p class="notice amber">기본 시연 모드 · AI 판단을 사용하지 않습니다.</p>':''}${button('기능·시연 범위 보기','integration','quiet small')}</section>`;}
  function photo(f,small=false){return `<figure class="facility-photo ${small?'compact':''}"><img src="assets/${f.id==='saebom'?'facility-lounge':f.id}.jpg" alt="${f.name}의 가상 시설 환경 예시 · AI 생성" width="1100" height="733" loading="lazy"></figure>`;}
  function goRole(r){if(r==='facility'&&state.stage===2&&autoEnabled){autoEnabled=false;generation++;autoRunId++;autoRunning=false;liveMessage='수용기관 직접 응답 모드';save();toast('직접 응답할 수 있도록 자동 진행을 일시 정지했습니다.');}if(r==='facility'&&state.stage===2&&!state.inquiries.includes(facility))facility=state.inquiries[0]||facility;role=r;if(r==='facility'&&state.selected)facility=state.selected;view='case';render();window.scrollTo({top:0,behavior:'smooth'});}
  function pageHead(title,sub){return `<div class="breadcrumb">전원·회송 연계 <span aria-hidden="true"> / </span> ${roles[role]}</div><div class="page-heading"><div><div class="eyebrow">${state.caseId} · ${state.scenario==='normal'?'정상 연계':state.scenario==='missing'?'회송 정보 누락':'수용 불가 후 재탐색'} 시나리오</div><h1>${title}</h1><p class="sub">${sub}</p></div>${badge(M.stages[state.stage],state.stage===7?'green':'navy')}</div>`;}
  function caseSummary(){return `<section class="case-summary" aria-label="회송 건 요약"><div><div class="caption">대상자 · 가상 데이터</div><div class="value">${role==='facility'&&(!state.shareConsent||state.selected!==facility)?'비식별 의뢰 대상자':state.patient} <span class="muted">/ ${state.age}</span></div><div class="small-text">${state.caseId} · 비응급 회송</div></div><div><div class="caption">필요 처치</div><div class="value">정맥 항생제 치료 지속</div><div class="small-text">의료적 적합성은 담당 의료진·수용기관이 판단</div></div><div><div class="caption">현재 담당</div><div class="value">${state.stage===0?'의뢰기관 · 정보 확인':state.stage===1?'환자 동의 / 의뢰기관 문의':state.stage===2?'수용기관 · 응답':state.stage===3?'환자·보호자 · 기관 선택':state.stage===4?'의뢰기관 · 전원 준비':state.stage===5?'수용기관 · 첫 진료 회신':state.stage===6?'의뢰기관 · 회신 확인':'의뢰기관 확인 완료'}</div><div class="small-text">${state.selected?esc(selected().name):'선택 기관 없음'}</div></div></section>`;}
  function steps(){return `<ol class="steps" aria-label="회송 진행 단계">${M.stages.map((x,i)=>`<li class="${i===state.stage?'current':i<state.stage?'done':''}" ${i===state.stage?'aria-current="step"':''}><span class="dot">${i<state.stage?'✓':i+1}</span>${x}</li>`).join('')}</ol>`;}
  const responseNames={accepted:['수용 가능','green'],rejected:['수용 불가','red'],more:['추가 정보 필요','amber'],withdrawn:['문의 종료',''],timeout:['응답 기한 초과','amber']};
  const responseBadge=f=>f.response?badge(...responseNames[f.response.status]):badge('응답 대기');
  function activity(limit=5){return state.events.length?`<ol class="activity">${state.events.slice(0,limit).map(e=>`<li><span class="actor">${roles[e.actor]}</span><time>${when(e.time)}</time><p>${esc(serviceText(e.detail))}</p></li>`).join('')}</ol>`:`<p class="muted">회송 정보를 확인하면 처리 기록이 이곳에 남습니다.</p>`;}
  function auditPanel(){return `<section class="panel"><div class="panel-head"><h2>최근 처리 기록</h2>${button('전체 보기','history','quiet small')}</div>${activity()}</section>`;}
  function clinicalPanel(){return `<section class="panel"><div class="panel-head"><h2>구조화된 회송 정보</h2>${badge(state.parsed?(M.missing(state).length?'보완 필요':'필수 항목 입력됨'):'구조화 전',state.parsed&&M.missing(state).length?'amber':'')}</div>${state.extraction?`<div class="notice green"><b>AI 분석 · 원문 대조 완료</b><br>${when(state.extraction.at)} 분석${state.extraction.cached?' · 확인된 분석 결과':''}</div>`:''}${state.parsed?dl(Object.entries(M.fields).map(([k,v])=>[v,state.data[k]?esc(state.data[k]):'<span class="missing-text">미기재 · 담당의 확인 필요</span>'])):`<div class="pending">회송서의 기재 항목을 추출하고, 누락 여부를 점검합니다. 문서에 없는 처치·용량·투여 간격은 추정하지 않습니다.</div>`}<p class="tiny" style="margin-top:12px">입력 여부 점검만 수행합니다. 처방의 적절성·임상 안전성을 검증하는 기능은 아닙니다.</p></section>`;}
  function facilityCard(f,patient=false){
    const status=statusBadge(U.facilityStatus(f,state));
    return `<article class="facility ${patient?'patient-facility':'staff-facility'} ${!f.eligible&&!patient?'excluded':''} ${compare.has(f.id)?'compare-selected':''} ${state.selected===f.id?'selection':''}">${photo(f,!patient)}<div class="facility-main"><div class="facility-title"><div><h3>${f.name}</h3><div class="type">${facilityType(f)} · ${f.area}</div></div>${status}</div><div class="match-score">조건 적합 점수 <b title="생활 조건 비교 점수이며 임상 적합성 평가가 아닙니다">${f.score}/100</b> <span>거리·비용·기관 평가·응답 이력</span></div><div class="facility-facts"><div><strong>${f.km} km</strong><span>보호자 거주지 기준</span></div><div><strong>${f.minutes}분</strong><span>예상 이동 시간</span></div><div><strong>${money(f.cost)}</strong><span>1일 예상 부담</span></div></div><div class="row capability-row">${capability('정맥 투여',f.iv)}${capability('격리 처치',f.isolation)}${!f.fresh?statusBadge({label:'기관 정보 재확인 필요',tone:'amber',icon:'!'}):''}</div>${state.lastAgent?.recommendations?.find(r=>r.id===f.id)?`<div class="recommendation-basis"><b>AI 추천 근거</b><ul>${state.lastAgent.recommendations.find(r=>r.id===f.id).basis.slice(0,3).map(x=>`<li>${displayFact(x)}</li>`).join('')}</ul></div>`:''}${f.response?.reason?`<p class="response-note"><b>기관 회신</b> ${displayFact(f.response.reason)}</p>`:''}${!f.eligible&&!patient?`<p class="exclusion-reason"><b>제외 사유</b> ${esc(f.reasons.join(' · '))}</p>`:''}</div><div class="facility-bottom"><span>${patient?'기관 회신과 생활 조건을 함께 확인해 주세요.':'정보 갱신 '+f.updated}</span><div class="row">${button('기관 정보 보기','detail','small',`data-id="${f.id}"`)}${patient&&M.accepted(state).length>1?button(compare.has(f.id)?'✓ 비교에 담음':'비교에 담기','compare',(compare.has(f.id)?'selected ':'')+'small',`data-id="${f.id}" aria-pressed="${compare.has(f.id)}"`):''}${patient?button('이 기관 선택','choose','primary small',`data-id="${f.id}"`):''}</div></div></article>`;
  }
  function highlightedText(text,clean=false,supplements=null){
    return U.sourceSegments(text).map(line=>{
      if(line.kind==='text')return `<p class="referral-note">${(clean?displayFact(line.text):esc(line.text))||'&nbsp;'}</p>`;
      let value;
      if(line.missing&&supplements?.[line.key])value=`<div class="supplemented-field"><span class="source-origin">원문 미기재</span><mark class="referral-token token-${line.kind}">${esc(supplements[line.key])}</mark><span class="supplement-label">담당의 보완 회신</span></div>`;
      else value=`<mark class="referral-token token-${line.missing?'missing':line.kind}">${line.missing?'<span aria-hidden="true">!</span> 미기재 · 보완 필요':(clean?displayFact(line.value):esc(line.value))}</mark>`;
      return `<div class="referral-tag-row"><span class="referral-field-name">${esc(line.label)}</span>${value}</div>`;
    }).join('');
  }
  function highlightedSource(){return highlightedText(state.source,false,state.parsed?state.data:null);}
  function referralDocument(){
    return `<section class="referral-document" aria-labelledby="referral-document-title"><div class="referral-document-toolbar"><h3 id="referral-document-title">회송서 원문</h3><div class="referral-view-switch" role="group" aria-label="회송서 보기 방식">${button('항목 강조','source-preview',!sourceEditMode?'selected':'',`aria-pressed="${!sourceEditMode}"`)}${button('원문 편집','source-edit',sourceEditMode?'selected':'',`aria-pressed="${sourceEditMode}"`)}</div></div><div class="tagged-referral" id="referral-highlight" role="document" aria-label="원문 항목 강조" ${sourceEditMode?'hidden':''}>${highlightedSource()}</div><div class="field" id="referral-editor" ${!sourceEditMode?'hidden':''}><label class="referral-editor-label" for="referral-source">자유서술 회송서 · 시연용 편집</label><textarea id="referral-source" rows="12" spellcheck="false">${esc(state.source)}</textarea><p class="tiny">편집한 내용은 ‘항목 강조’에서 바로 확인할 수 있습니다.</p></div></section>`;
  }
  function setSourceView(edit){
    sourceEditMode=edit;const preview=$('#referral-highlight'),editor=$('#referral-editor');if(!preview||!editor)return;
    preview.innerHTML=highlightedSource();preview.hidden=edit;editor.hidden=!edit;
    for(const b of document.querySelectorAll('.referral-view-switch button')){const active=(b.dataset.action==='source-edit')===edit;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));}
    if(edit)$('#referral-source')?.focus({preventScroll:true});
  }
  function hospital(){
    let out=pageHead(state.stage===7?'첫 진료까지 연결되었습니다':'회송 진행 관리','회송 정보와 기관 응답을 한곳에서 확인합니다. 예외와 실제 준비 업무에 필요한 작업만 수행합니다.')+caseSummary()+steps();
    if(state.stage===0){
      out+=`<div class="grid"><div><section class="panel"><div class="panel-head"><h2>회송서 확인</h2>${badge('가상 문서','navy')}</div><p class="sub">의사가 회송을 결정한 이후의 업무를 다룹니다. 실제 환자 정보를 입력하지 마세요.</p>${referralDocument()}${checks('attest','담당의가 비응급 전원·회송을 결정했음을 확인했습니다.',state.doctorApproved)}<div class="row">${button(!apiChecked?'AI 연결 확인 중…':aiAvailable?'AI로 회송서 분석':'AI 분석 연결 확인 필요','ai-parse',aiAvailable?'primary':'small',!apiReady||!aiAvailable||state.source!==M.initial(state.scenario).source?'disabled':'')}${button('기본 항목 점검','parse',aiAvailable?'small':'primary')}</div><p class="tiny">예시 회송서를 분석해 항목을 정리합니다. 편집한 문서는 기본 항목 점검을 사용하세요.</p>${aiError?`<p class="notice amber" role="alert">${esc(serviceText(aiError))}</p>`:''}<div class="row"></div></section>${state.parsed&&M.missing(state).length?`<section class="panel"><h2>담당의 보완이 필요한 항목</h2><div class="notice amber">${M.missing(state).map(k=>M.fields[k]).join(', ')} 정보가 없습니다. 처방 내용을 임의로 채우지 않습니다.</div>${button('담당의 보완 회신 입력 (시연)','supplement','primary')}</section>`:''}</div><div>${clinicalPanel()}${state.parsed&&!M.missing(state).length?`<section class="panel footer-action"><div><h3>기관 문의를 준비할 수 있습니다.</h3><p class="tiny">의료적 적합성 판단은 담당 의료진의 책임입니다.</p></div>${button('기관 문의 준비','ready','primary')}</section>`:''}${auditPanel()}</div></div>`;
    }else if(state.stage===1){
      const fs=M.candidates(state),eligible=fs.filter(f=>f.eligible);
      out+=`<div class="grid"><div><div class="toolbar"><h2>처치 조건에 맞는 기관 <span class="muted">${eligible.length}곳</span></h2>${badge('희망 이동 범위 '+M.profile(state).maxKm+'km')}</div><div class="list">${eligible.map(f=>facilityCard(f)).join('')}</div><details><summary>제외된 기관과 사유 보기 (${fs.length-eligible.length})</summary><div class="list">${fs.filter(f=>!f.eligible).map(f=>facilityCard(f)).join('')}</div></details></div><div><section class="panel"><h2>문의 전 확인</h2>${dl([['처치 정보','필수 항목 기재 확인'],['문의 범위','가상 '+eligible.length+'개 기관'],['환자 동의',state.consent?'<span class="badge green">동의 확인</span>':'<span class="badge amber">동의 필요</span>'],['전달 정보','비식별 처치 요약 · 연령대 · 희망 조건']])}<div class="notice">이름·연락처·상세 처방은 초기 문의에 포함하지 않습니다. 기관 응답은 실제 수용 확정과 구분됩니다.</div>${!state.consent?button('환자 동의 화면 열기','go-patient','primary'):button('비식별 수용 문의 생성','send','primary')}<p class="tiny" style="margin-top:12px">가상 기관에 문의 항목을 생성합니다. 외부로 전송하지 않습니다.</p></section>${auditPanel()}</div></div>`;
    }else if(state.stage===2){
      const fs=M.candidates(state).filter(f=>state.inquiries.includes(f.id)),n=M.accepted(state).length;
      out+=`<div class="grid"><div><div class="toolbar"><h2>기관 응답 현황</h2><div class="row">${badge('수용 가능 '+n+'곳','green')}${badge('미응답 '+fs.filter(f=>!f.response).length+'곳')}</div></div><div class="list">${fs.map(f=>facilityCard(f)).join('')}</div></div><div><section class="panel"><h2>다음 작업</h2><p class="sub">수용 가능 응답을 받은 기관만 환자에게 공개합니다. 추가 정보 요청 기관은 선택 후보에 포함하지 않습니다.</p><div class="row">${button('수용기관 응답 화면','go-facility','primary')}${button('가상 응답 불러오기','demo','small')}</div><div class="notice">‘가상 응답 불러오기’는 준비된 시연값을 채웁니다. 실제 기관 문의·응답이나 실시간 병상 정보가 아닙니다.</div>${n?button('수용 확인된 기관을 환자에게 공개','publish','primary'):''}${Object.keys(state.responses).length&&!n?`<div class="notice amber">수용 가능한 기관이 없습니다. 담당자가 생활 조건을 다시 확인하고 탐색 범위를 조정해야 합니다.</div>${button('탐색 범위 확장·재문의','expand','primary')}`:''}</section>${auditPanel()}</div></div>`;
    }else if(state.stage===3){out+=`<div class="grid"><div><section class="state-banner"><div class="state-index">4</div><div><h2>환자·보호자의 선택을 기다립니다.</h2><p>수용이 확인된 ${M.accepted(state).length}개 기관의 거리·비용·처치 정보를 비교할 수 있습니다.</p><div style="margin-top:15px">${button('환자 비교 화면 열기','go-patient','primary')}</div></div></section>${M.accepted(state).map(f=>facilityCard(f)).join('')}</div><div>${auditPanel()}</div></div>`;
    }else if(state.stage===4){out+=`<div class="grid"><div><section class="panel"><h2>선택 기관 · ${selected().name}</h2>${dl([['환자 선택','환자·보호자 직접 선택'],['정보 제공','선택 기관 한정 전달 동의 기록'],['다른 문의','선택하지 않은 기관의 문의 종료'],['전원 상태','전원 준비 중 · 진료 완료 아님']])}<div class="notice green">환자가 기관을 선택했습니다. 기존 업무에서 필요한 서류·이동·안내 사항을 준비합니다.</div></section><section class="panel"><h2>전원 준비 확인</h2>${checks('prep-documents','기존 절차에 따른 회송 서류와 원 처방 정보를 확인했습니다.',state.prep.documents)}${checks('prep-transport','수용기관과 이동·입원 일정을 확인했습니다.',state.prep.transport)}${checks('prep-guidance','환자·보호자에게 기존 의료진의 안내를 전달했습니다.',state.prep.guidance)}${button('공식 회송 전달 기록 생성 (시연)','handoff','primary')}<p class="tiny" style="margin-top:12px">실제 EMR·HIRA 연동이나 청구를 하지 않습니다. 자동 처방·전원 판단을 수행하지 않습니다.</p></section></div><div>${auditPanel()}</div></div>`;
    }else if(state.stage===5){out+=`<div class="grid"><div><section class="state-banner"><div class="state-index">6</div><div><h2>수용기관의 첫 진료 회신을 기다립니다.</h2><p>문서 전달만으로 연계를 완료 처리하지 않습니다. ${selected().name}에서 실제 첫 진료 이행 여부를 회신해야 합니다.</p><div style="margin-top:15px">${button('수용기관 회신 화면 열기','go-facility','primary')}</div></div></section><section class="panel"><h2>인계 기록</h2>${dl([['선택 기관',selected().name],['진행 상태','전원 준비 확인 · 전달 기록 생성 (시연)'],['첫 진료','수용기관 회신 대기'],['연계 완료','의뢰기관 회신 확인 후 처리']])}</section></div><div>${auditPanel()}</div></div>`;
    }else if(state.stage===6){out+=`<div class="grid"><div><section class="panel"><div class="panel-head"><h2>수용기관 첫 진료 회신</h2>${badge(state.visit.result==='done'?'이행 회신':'미이행 · 예외 처리',state.visit.result==='done'?'green':'red')}</div>${dl([['회신 기관',selected().name],['첫 진료',state.visit.result==='done'?'진료 이행':'진료 미이행'],['회신 시각',when(state.visit.at)],['추가 메모',esc(state.visit.note||'별도 메모 없음')]])}<div class="notice ${state.visit.result==='done'?'green':'amber'}">${state.visit.result==='done'?'의뢰기관 담당자가 회신을 확인해야 연계가 완료됩니다.':'미이행 사유를 확인하고 재연계합니다. 시스템이 자동으로 완료 처리하지 않습니다.'}</div>${state.visit.result==='done'?button('의뢰기관 회신 확인·연계 완료','ack','primary'):button('미이행 건 재연계','relink','primary')}</section></div><div>${auditPanel()}</div></div>`;
    }else{out+=completion();}return out;
  }
  function completion(){return `<section class="panel complete"><div class="symbol">✓</div><h1>의뢰기관의 확인까지 마쳤습니다.</h1><p class="sub" style="margin:auto">수용기관의 첫 진료 이행 회신과 의뢰기관 담당자의 확인 기록이 모두 남았습니다.</p><div class="cards-inline" style="justify-content:center"><div><strong>${selected().name}</strong><span>선택한 수용기관</span></div><div><strong>첫 진료 이행</strong><span>수용기관 회신</span></div><div><strong>확인 완료</strong><span>의뢰기관 담당자</span></div></div><div class="row" style="justify-content:center">${button('처리 기록 보기','history','primary')}${button('시연 기록 내려받기','export')}${button('다시 시연하기','reset')}</div><p class="tiny" style="margin-top:18px">시나리오의 완료 상태입니다. 실제 환자 연계나 임상 성과를 나타내지 않습니다.</p></section>${auditPanel()}`;}
  function patientPreferences(){
    const currentProfile=M.profile(state),radius=currentProfile.maxKm;
    let consent=state.stage===0?'<p class="notice">의뢰기관에서 회송 정보를 확인한 뒤 기관 문의에 동의할 수 있습니다.</p>':state.consent?checks('consent','기관 문의 동의가 기록되었습니다.',true,'체크를 해제하면 진행 중인 문의를 중단하고 동의 단계로 돌아갑니다.'):checks('consent-draft','비식별 정보를 이용한 기관 문의에 동의합니다.',consentDraft,'제공 범위: 처치 요약·연령대·희망 조건. 이름·연락처·상세 처방은 기관 선택 후 별도 동의로 전달합니다.')+button('동의하고 기관 찾기','consent-start','primary',consentDraft?'':'disabled')+'<p class="tiny">동의 항목을 체크한 뒤 시작 버튼을 눌러 주세요.</p>';
    const form=`<section class="panel preference-panel" id="patient-preferences"><div class="panel-head"><h2>희망 조건과 기관 문의 동의</h2>${badge('의료 판단과 별도로 반영')}</div><p class="sub">가상 희망 조건을 선택하면 필수 조건과 추천 가중치에 반영합니다.</p><div class="profile-options">${Object.entries(M.profiles).map(([id,p])=>button(p.label,'select-profile',state.preferences.profile===id?'selected':'',`data-id="${id}" aria-pressed="${(state.preferences.profile||'balanced')===id}"`)).join('')}</div><p class="profile-quote">“${esc(currentProfile.text)}”</p><p class="tiny">탐색 범위 ${radius}km${currentProfile.maxCost?' · 하루 '+money(currentProfile.maxCost)+' 이하':''}${currentProfile.maxMinutes?' · 이동 '+currentProfile.maxMinutes+'분 이내':''} · 기관·거리·금액·평가·응답 이력은 시연값입니다. 조건 변경 후에는 문의 동의를 다시 확인합니다.</p>${consent}</section>`;
    return state.stage===3?`<details class="preferences-summary"><summary><span>희망 조건: ${currentProfile.label} · ${radius}km 이내</span>${statusBadge({label:'문의 동의 완료',tone:'green',icon:'✓'})}<span class="preferences-edit">조건 수정 / 동의 철회</span></summary>${form}</details>`:form;
  }
  function patient(){
    let out=pageHead('다음 진료를 받을 곳을 함께 고릅니다.','처치 가능 여부를 확인한 기관 중에서 생활 조건에 맞는 곳을 비교해 주세요.')+caseSummary()+steps();
    if(state.stage<4)out+=patientPreferences();
    if(state.stage<3){out+=`<section class="empty-hint"><h2>${state.stage===2?'기관의 수용 응답을 기다리고 있어요.':'회송 정보와 기관 문의를 준비하고 있어요.'}</h2><p class="sub">수용이 확인되면 기관별 거리·비용·처치 정보를 비교할 수 있습니다. 목록에 있다는 이유만으로 수용이 확정되지는 않습니다.</p>${button('의뢰기관 진행 화면 열기','go-hospital','primary')}</section>`;}
    else if(state.stage===3){out+=`<div class="toolbar"><div><h2>수용이 확인된 기관 ${M.accepted(state).length}곳</h2><p class="tiny">의료진·기관의 판단을 바탕으로, 환자·보호자가 최종 선택합니다.</p></div><div class="row">${state.lastAgent?button('AI 추천·문의·회신 근거','agent-detail','quiet small'):''}${M.accepted(state).length>1?button('담은 기관 나란히 비교 ('+compare.size+')','open-compare','',compare.size<2?'disabled':''):''}</div></div><div class="patient-grid">${M.accepted(state).map(f=>facilityCard(f,true)).join('')}</div><div class="notice">비용·이동 시간·수용 여부는 해당 기관에서 최종 확인해야 합니다. 기관의 유료 노출·광고 순위는 사용하지 않습니다.</div>${button('맞는 기관이 없어요 · 조건 다시 찾기','reject-candidates','small')}`;}
    else{out+=`<section class="panel"><div class="panel-head"><h2>${selected().name}을 선택했어요.</h2>${badge(state.stage===7?'연계 완료':state.stage>=6?'첫 진료 회신 도착':'연계 진행 중',state.stage===7?'green':'navy')}</div>${dl([['이동 정보',selected().area+' · 이동 '+selected().minutes+'분'],['정보 전달','선택한 기관에 한정하여 동의 기록'],['현재 상태',M.stages[state.stage]],['다음 안내',state.stage===4?'의뢰기관에서 전원 준비를 확인하고 있습니다.':state.stage===5?'첫 진료 이행 여부를 수용기관이 회신할 예정입니다.':state.stage===6&&state.visit?.result==='missed'?'첫 진료가 이루어지지 않아 담당자가 재연계를 확인합니다.':state.stage===6?'의뢰기관에서 수용기관의 회신을 확인하고 있습니다.':'의뢰기관의 첫 진료 회신 확인까지 완료했습니다.']])}</section>`;}return `<div class="patient-layout">${out}</div>`;
  }
  function facilityView(){
    const f=M.candidates(state).find(f=>f.id===facility),sum=M.summary(state,facility),received=state.inquiries.includes(f.id),r=state.responses[f.id];
    let out=pageHead('수용 문의와 진료 이행 회신','기관의 처치 가능 여부와 실제 수용 조건은 수용기관 담당자가 판단합니다.');
    out+=`<section class="panel"><div class="row space"><div><h2>${f.name}</h2><p class="tiny">가상 수용기관 · 역할 전환은 시연을 위한 기능이며 실제 인증이 아닙니다.</p></div><label class="field" style="margin:0"><span>시연할 기관</span><select id="facility-select">${M.facilities.map(x=>`<option value="${x.id}" ${x.id===facility?'selected':''}>${x.name}</option>`).join('')}</select></label></div><div class="row">${capability('정맥 투여',f.iv)}${capability('격리 처치',f.isolation)}${badge('정보 갱신 '+f.updated)}</div></section>`;
    out+=`<details class="provider-settings panel"><summary>기관 처치 역량·병상 등록</summary><p class="tiny">기관이 직접 등록한 정보는 후보 필터에 반영됩니다. 환자별 수용 응답과는 구분됩니다.</p><label class="field"><span>등록 병상 수</span><input id="provider-beds" type="number" min="0" max="20" value="${f.beds}"></label><label class="check"><input type="checkbox" id="provider-iv" ${f.iv?'checked':''}><span>정맥 투여 처치 가능</span></label><label class="check"><input type="checkbox" id="provider-isolation" ${f.isolation?'checked':''}><span>격리 처치 가능</span></label>${button('기관 등록 정보 저장','provider-save','',state.stage>=4?'disabled':'')}<p class="tiny">기관 선택 전까지 시연 정보를 바꿀 수 있습니다.</p></details>`;
    if(!received){return out+`<section class="empty-hint"><h2>현재 이 기관에 생성된 문의가 없습니다.</h2><p class="sub">의뢰기관에서 처치 조건을 확인한 뒤 문의 대상 기관에 비식별 요약을 생성합니다.</p>${button('의뢰기관 화면 열기','go-hospital','primary')}</section>`;}
    if(r?.status==='withdrawn'){return out+`<section class="panel"><h2>문의가 종료되었습니다.</h2><p class="sub">환자가 다른 기관을 선택했습니다. 이 기관에는 환자의 상세 정보가 공개되지 않습니다.</p>${badge('추가 정보 접근 없음')}</section>`;}
    out+=`<div class="grid"><div><section class="panel"><div class="panel-head"><h2>${sum.shared?'선택 기관 한정 회송 정보':'비식별 수용 문의 요약'}</h2>${badge(sum.shared?'정보 전달 동의 기록':'개인식별정보 미포함','navy')}</div>${dl([['문의 번호',state.caseId],['연령대',sum.age],['필요 처치',esc(sum.treatment)],['치료 기간',esc(sum.period)],['격리 여부',esc(sum.isolation)],...(sum.shared?[['가상 대상자',sum.patient],['약제',esc(sum.drug)],['용량',esc(sum.dose)],['투여 간격',esc(sum.interval)]]:[])])}${!sum.shared?'<div class="locked">환자 이름·연락처·상세 처방은 기관 선택과 정보 제공 동의 전에는 공개하지 않습니다.</div>':''}</section></div><div>`;
    if(state.stage===2){out+=`<section class="panel"><h2>수용 여부 응답</h2><p class="sub">처치 역량과 희망 일정의 실제 수용 가능성을 함께 확인해 주세요.</p><label class="field"><span>응답</span><select id="response-status"><option value="" disabled ${!r?'selected':''}>수용 여부를 선택해 주세요</option><option value="accepted" ${r?.status==='accepted'?'selected':''}>수용 가능</option><option value="more" ${r?.status==='more'?'selected':''}>추가 정보 필요</option><option value="rejected" ${r?.status==='rejected'?'selected':''}>수용 불가</option></select></label><label class="field"><span>조건 또는 사유</span><textarea id="response-reason" style="min-height:90px" placeholder="수용 조건, 추가로 필요한 정보, 수용 불가 사유">${esc(r?.reason||'')}</textarea></label>${button('수용 응답 기록','response','primary')}<p class="tiny" style="margin-top:12px">실제 병상 예약이나 임상적 수용 결정이 아닌 가상 응답 기록입니다.</p></section>`;}
    else if(state.selected===facility&&state.stage===5){out+=`<section class="panel"><h2>첫 진료 이행 회신</h2><label class="field"><span>진료 이행 여부</span><select id="visit-result"><option value="" disabled selected>이행 여부를 선택해 주세요</option><option value="done">첫 진료 이행</option><option value="missed">첫 진료 미이행</option></select></label><label class="field"><span>추가 확인 사항</span><textarea id="visit-note" style="min-height:90px" placeholder="미이행 시 확인된 사유 등을 기록합니다."></textarea></label>${button('의뢰기관에 회신 기록','visit','primary')}<div class="notice">회신 후 의뢰기관 담당자의 확인을 기다립니다. 이 화면에서 연계를 최종 완료하지 않습니다.</div></section>`;}
    else{out+=`<section class="panel"><h2>${state.stage===7?'의뢰기관 확인 완료':state.stage===6?'의뢰기관 확인 대기':state.selected===facility?'전원 준비 중':'환자 선택 대기'}</h2><p class="sub">${state.stage===4?'의뢰기관에서 기존 회송 절차에 따른 전원 준비를 진행합니다.':state.stage>=6?'첫 진료 회신은 의뢰기관에서 확인합니다.':'응답을 기록했습니다. 수용이 확인된 기관 중 환자가 직접 선택합니다.'}</p>${button('의뢰기관 진행 확인','go-hospital','small')}</section>`;}return out+'</div></div>';
  }
  const flow=[['회송 정보','담당의 회송 결정을 확인하고 문서의 필수 항목을 점검합니다. 누락된 내용은 담당의 보완 회신으로만 채웁니다.','의뢰기관·의사'],['기관 문의','환자 동의를 확인한 뒤 처치 조건에 맞는 기관에 비식별 요약 문의를 생성합니다.','환자·의뢰기관'],['수용 응답','수용기관이 가능·불가·추가 확인을 회신합니다. 불가·무응답이면 범위를 조정합니다.','수용기관'],['환자 선택','수용 확인된 기관만 비교합니다. 환자가 선택하고 해당 기관에 대한 정보 제공에 동의합니다.','환자·보호자'],['전원 준비','선택 기관에 한정해 정보를 전달하고 기존 회송 업무의 준비 사항을 확인합니다.','의뢰기관'],['첫 진료 회신','수용기관에서 첫 진료 이행 또는 미이행을 회신합니다.','수용기관'],['의뢰기관 확인','회신 내용을 담당자가 확인합니다. 미이행이면 완료 처리 대신 재연계합니다.','의뢰기관'],['연계 완료','수용기관의 진료 이행과 의뢰기관의 회신 확인이 모두 기록된 상태입니다.','의뢰기관']];
  function flowPage(){return pageHead('서비스 흐름','하나의 회송 건을 세 역할의 화면에서 이어서 시연합니다.')+`<section class="panel">${flow.map(([title,desc,owner],i)=>`<div class="flow-row ${i===state.stage?'active':''}"><span class="flow-num">${i+1}</span><div><h3>${title}</h3><p>${desc}</p></div><span class="owner">${owner}</span></div>`).join('')}</section><div class="notice">자동화 대상은 정보 정리와 문의·회신의 상태 관리입니다. 진단·처방·의료적 수용 판단은 자동화하지 않습니다.</div>`;}
  function historyPage(){return pageHead('회송 처리 기록','역할별 작업과 예외 처리 흐름을 확인하고, 가상 시연 기록을 내려받을 수 있습니다.')+`<section class="panel"><div class="row space"><h2>${state.caseId}</h2>${button('시연 기록 내려받기','export','primary')}</div><div class="cards-inline"><div><strong>${state.events.length}건</strong><span>이 브라우저의 기록된 작업</span></div><div><strong>${state.metrics.errors}회</strong><span>진행 조건 미충족 시도</span></div><div><strong>${M.stages[state.stage]}</strong><span>현재 단계</span></div></div><p class="tiny">위 수치는 합성 시연의 조작 기록입니다. 실제 업무 절감량·효과 지표가 아닙니다.</p>${activity(300)}</section>`;}
  function guide(){return pageHead('프로토타입 안내','설계된 업무 흐름과 가상 상태 전환을 검증하는 1차 시연 버전입니다.')+`<section class="panel readme"><h2>정상 시나리오 · 약 3분</h2><ol><li>의뢰기관: 담당의 회송 결정 확인 → 회송 정보 구조화 → 기관 문의 준비</li><li>환자·보호자: 선호 조건 선택 → 비식별 문의 동의</li><li>의뢰기관: 비식별 수용 문의 생성 → 가상 응답 불러오기 → 후보 공개</li><li>환자·보호자: 기관 상세 확인·나란히 비교 → 기관 선택 및 정보 전달 동의</li><li>의뢰기관: 전원 준비 확인 → 공식 회송 전달 기록 생성 (시연)</li><li>수용기관: 선택 기관에서 첫 진료 이행 회신</li><li>의뢰기관: 회신 확인 → 연계 완료</li></ol><h2>예외 시나리오</h2><p>‘정보 누락’은 투여 간격이 비어 있어 문의로 넘어갈 수 없습니다. 담당의 보완 회신을 입력해야 합니다. ‘수용 불가’는 첫 문의의 모든 기관이 거절하여 재탐색이 필요합니다. 첫 진료 회신에서 ‘미이행’을 선택하면 완료 대신 재연계합니다.</p><h2>현재 구현된 것과 모의 기능</h2>${dl([['동작하는 기능','역할별 화면, 규칙 기반 필수 항목 점검, 후보 필터·정렬, 기관 응답, 비교·선택, 전달 범위, 단계별 진행 조건, 처리 기록·JSON 내보내기'],['모의 기능','LLM, EMR/FHIR, HIRA 공식 중계, 지도 거리, 실제 병상·금액, 알림톡·문자 전송'],['데이터','모든 환자·기관·가격·처방·응답은 합성 시연값'],['저장','이 브라우저의 로컬 저장소에만 진행 상태 저장. 다른 기기·역할 간 서버 동기화 없음.'],['인증','화면 상단의 역할 전환은 실제 로그인·권한 보안이 아님.'],['제외 범위','응급 전원, 자택 귀가, 임상 적합성 판단, 수가·청구 계산, 첫 진료 이후 장기 추적']])}</section>`;}
  function renderBase(){
    const help=state.stage===0?'의뢰기관에서 회송 정보를 확인해 주세요.':state.stage===1&&!state.consent?'환자·보호자 화면에서 비식별 문의 동의를 확인해 주세요.':state.stage===1?'의뢰기관에서 수용 문의를 생성할 수 있어요.':state.stage===2?'수용기관 화면에서 응답하거나, 가상 응답을 불러와 주세요.':state.stage===3?'환자·보호자가 수용 확인된 기관을 비교·선택할 차례예요.':state.stage===4?'의뢰기관에서 기존 전원 준비 항목을 확인해 주세요.':state.stage===5?'선택한 수용기관에서 첫 진료 이행 여부를 회신해 주세요.':state.stage===6?'의뢰기관이 회신을 확인해야 연계가 끝납니다.':'첫 진료 이행과 의뢰기관 확인까지 마쳤어요.';
    $('#app').innerHTML=`<div class="demo-strip"><span><strong>서비스 프로토타입</strong> · 회송 사례·기관 응답은 가상입니다. 실제 환자 정보를 입력하지 마세요.</span><span>실제 의료정보·기관·EMR 연결 없음</span></div><header><a class="brand" href="/" data-action="home" aria-label="케어브릿지 첫 화면으로"><div class="brand-mark" aria-hidden="true">cb</div><div><strong>케어브릿지</strong><span>CAREBRIDGE</span></div></a><div class="role-group"><span class="role-label">시연 역할 선택</span><nav class="role-tabs" aria-label="시연 역할 선택">${Object.entries(roles).filter(([k])=>k!=='simulation').map(([k,v])=>button(v,'role',role===k?'active':'',`data-role="${k}" aria-pressed="${role===k}"`)).join('')}</nav></div><div class="header-actions">${button('시연 안내','guide','quiet small')}${button('서비스 흐름','flow','small')}${button('처음부터','reset','quiet small')}</div></header><div class="walkthrough"><b>다음 단계</b><span>${help}</span></div><div class="workspace"><aside class="sidebar"><div class="side-label">WORKSPACE</div><nav class="side-nav" aria-label="작업 메뉴">${button('회송 업무 <span class="number">1</span>','case',view==='case'?'active':'')}${button('처리 기록 <span class="number">'+state.events.length+'</span>','history',view==='history'?'active':'')}${button('서비스 흐름','flow',view==='flow'?'active':'')}${button('공개 기관 정보 조회','hospitals',view==='hospitals'?'active':'')}${button('시연 안내','guide',view==='guide'?'active':'')}</nav><div class="side-rule"></div><div class="scenario"><label for="scenario-select">가상 시나리오</label><select id="scenario-select"><option value="normal" ${state.scenario==='normal'?'selected':''}>정상 연계</option><option value="missing" ${state.scenario==='missing'?'selected':''}>회송 정보 누락</option><option value="unavailable" ${state.scenario==='unavailable'?'selected':''}>수용 불가·재탐색</option></select></div><p class="side-note"><b>비응급 회송</b><br>기관 탐색부터<br>첫 진료 이행 확인까지.</p><p class="side-note">이 화면은 시연용입니다.<br>실제 처치 판단과 수용 결정은 의료진·기관이 수행합니다.</p></aside><main id="main" tabindex="-1">${view==='hospitals'?hospitalsPage():view==='flow'?flowPage():view==='history'?historyPage():view==='guide'?guide():role==='hospital'?hospital():role==='patient'?patient():facilityView()}<footer class="app-footer">케어브릿지 · 팀 프로젝트 프로토타입 v5 &nbsp; / &nbsp; 가상 사례 1건 · 브라우저 내 저장 · 실제 의료 업무에 사용 불가</footer></main></div>`;
  }
  function render(){renderBase();enhance();enhanceUX();if(working)setBusy(true);}
  function modal(title,content,actions=''){const d=$('#dialog');d.classList.toggle('wide',title==='선택한 기관 비교');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('닫기','close','quiet small','aria-label="대화상자 닫기"')}</div><div class="dialog-body">${content}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();enhance();updateFormReadiness();}
  function close(){if($('#dialog').open)$('#dialog').close();}
  function detail(id){const f=M.candidates(state).find(x=>x.id===id);modal(f.name,`<p class="sub">${facilityType(f)} · ${f.area}</p>${dl([['필요 처치',capability('정맥 투여',f.iv)],['격리 역량',capability('격리 처치',f.isolation)],['이동 거리',f.km+'km · '+f.minutes+'분'],['예상 비용',money(f.cost)+' / 1일'],['기관 평가·응답 이력',f.quality+'/100 · 응답률 '+f.responseRate+'% · 불일치 '+f.mismatchRate+'%'],['기관 등록 병상',f.beds+'개'],['정보 갱신',f.updated],['수용 응답',f.response?displayFact(responseNames[f.response.status][0]+' · '+(f.response.reason||'')):'수용기관의 별도 확인 필요'],['후보 포함 근거',f.eligible?'처치 조건과 이동 범위 충족. 수용 여부는 별도 응답으로 확인.':esc(f.reasons.join(', '))]])}<div class="notice">기관 등록 역량·현재 수용 응답·환자 선택은 서로 다른 단계입니다. 비용과 품질을 임상적 적합성의 근거로 대신하지 않습니다.</div>`);}
  async function dispatch(event){
    const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
    if(a==='source-edit'||a==='source-preview'){setSourceView(a==='source-edit');return;}
    if(a==='home'){event.preventDefault();close();goRole('hospital');$('#main')?.focus({preventScroll:true});return;}
    if(a==='close'){close();return;}
    if(a.startsWith('focus-')){const selectors={'focus-attest':'[data-change="attest"]','focus-consent':'[data-change="consent-draft"]','focus-candidates':'.patient-grid','focus-preferences':'#patient-preferences','focus-response':'#response-status','focus-visit':'#visit-result','focus-prep':'[data-change^="prep-"]:not(:checked)'};const target=$(selectors[a]||'#main');if(target){(target.closest('.panel')||target).scrollIntoView({behavior:'smooth',block:'center'});(a==='focus-candidates'?target.querySelector('button'):target)?.focus?.({preventScroll:true});}return;}
    if(a==='reject-candidates'){modal('후보가 맞지 않는 이유',`<p class="sub">선택한 사유를 다음 탐색의 필수 조건과 가중치에 반영합니다. 새 조건으로 문의하기 전에 동의를 다시 확인합니다.</p><label class="field"><span>다시 찾는 이유 (가상)</span><select id="reject-reason"><option value="distance">보호자가 더 가까운 곳에 방문해야 해요</option><option value="cost">하루 비용을 4만원 이내로 줄이고 싶어요</option><option value="time">이동 시간이 30분 이내여야 해요</option></select></label>`,button('취소','close')+button('사유 반영하고 다시 찾기','confirm-reject','primary'));return;}
    if(a==='confirm-reject'){compare.clear();consentDraft=false;agentError='';if(await act({type:'rejectCandidates',reason:$('#reject-reason').value},'patient'))close();return;}
    if(a==='select-profile'){compare.clear();consentDraft=false;agentError='';await act({type:'profile',profile:id},'patient');return;}
    if(a==='retry-agent'){agentError='';if(autoEnabled&&(state.stage===1||state.stage===2))kickAutomation();else await runAgent();return;}
    if(a==='basic-demo'){basicMode=true;agentError='';autoEnabled=true;save();render();kickAutomation();return;}
    if(a==='provider-save'){await act({type:'facilityUpdate',id:facility,beds:Number($('#provider-beds').value),iv:$('#provider-iv').checked,isolation:$('#provider-isolation').checked},'facility');return;}
    if(a==='agent-detail'){agentDetail();return;}
    if(a==='agent-workflow'){close();goRole(nextRole());return;}
    if(a==='timeout-demo'){autoEnabled=false;save();const next=state.inquiries.find(id=>!state.responses[id]);if(next){await act({type:'timeout',id:next},'simulation');toast('무응답 예외를 기록했습니다. 자동 진행을 다시 켜면 나머지 문의를 처리합니다.');}return;}
    if(a==='consent-start'){if(!consentDraft){toast('먼저 기관 문의 동의를 확인해 주세요.',true);return;}if(await act({type:'consent',value:true},'patient'))consentDraft=false;return;}
    if(a==='clear-compare'){compare.clear();render();return;}

    if(a==='next-role'){goRole(nextRole());return;}
    if(a==='toggle-auto'){autoEnabled=!autoEnabled;if(autoEnabled)agentError='';if(!autoEnabled){generation++;autoRunId++;autoRunning=false;}liveMessage='자동 진행 준비';save();render();if(autoEnabled)kickAutomation();return;}
    if(a==='integration'){integrationModal();return;}
    if(a==='retry-api'){await checkApi();integrationModal();return;}
    if(a==='route'){await loadRoute(id);return;}
    if(a==='more-info'){modal('추가 정보 회신',`<p class="sub">${esc(M.facilities.find(f=>f.id===id).name)}의 요청: ${esc(state.responses[id].reason)}</p><label class="field"><span>담당의가 확인한 보완 내용 (가상)</span><textarea id="inquiry-note" placeholder="담당의의 보완 회신을 입력해 주세요."></textarea></label><label class="check"><input type="checkbox" id="inquiry-attest"><span>담당의가 확인한 정보임을 확인합니다. (시연)</span></label>`,button('취소','close')+button('보완 회신 전달','send-info','primary',`data-id="${id}"`));return;}
    if(a==='send-info'){if(await act({type:'provideInfo',id,note:$('#inquiry-note').value,confirmed:$('#inquiry-attest').checked})){close();toast('보완 내용을 전달했습니다. 기관 재응답을 기다립니다.');}return;}
    if(a==='role'){goRole(el.dataset.role);return;}
    if(a.startsWith('go-')){goRole(a.slice(3));return;}
    if(['case','history','flow','guide'].includes(a)){view=a;render();window.scrollTo(0,0);return;}
    if(a==='ai-parse'){await analyzeAI();return;}
    if(a==='hospitals'){view='hospitals';render();if(!hospitalResults)loadHospitals();return;}
    if(a==='hospital-map'){hospitalFocus=hospitalResults?.items.find(f=>f.id===id)||null;render();document.querySelector('.directory-map')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
    if(a==='hospital-search'){await loadHospitals();return;}
    if(a==='parse'){state.extraction=null;aiError='';const val=$('#referral-source').value;if(val!==state.source&&!await act({type:'source',value:val}))return;await act({type:'parse'});return;}
    if(['ready','send','publish','expand','handoff','ack','relink'].includes(a)){if(await act({type:a})){toast(a==='ack'?'의뢰기관 확인까지 완료했습니다.':a==='send'?'가상 수용 문의를 생성했습니다.':'진행 상태를 반영했습니다.');}return;}
    if(a==='demo'){if(await act({type:'demoResponses'},'simulation'))toast('미리 준비한 가상 기관 응답을 불러왔습니다.');return;}
    if(a==='priority-distance'||a==='priority-cost'){await act({type:'preferences',priority:a.split('-')[1]});return;}
    if(a==='response'){await act({type:'response',id:facility,status:$('#response-status').value,reason:$('#response-reason').value});return;}
    if(a==='visit'){await act({type:'visit',id:facility,result:$('#visit-result').value,note:$('#visit-note').value});return;}
    if(a==='detail'){detail(id);return;}
    if(a==='compare'){compare.has(id)?compare.delete(id):compare.add(id);render();return;}
    if(a==='open-compare'){
      const fs=M.accepted(state).filter(f=>compare.has(f.id));if(fs.length<2){toast('두 기관 이상을 비교에 담아 주세요.');return;}
      modal('선택한 기관 비교',`<div class="table-scroll"><table class="comparison-table"><thead><tr><th>비교 항목</th>${fs.map(f=>`<th>${f.name}</th>`).join('')}</tr></thead><tbody>${[['시설 예시',f=>photo(f,true)],['기관 유형',f=>facilityType(f)],['이동 거리',f=>f.km+'km'],['예상 이동',f=>f.minutes+'분'],['1일 예상 비용',f=>money(f.cost)],['조건 적합 점수',f=>f.score+'/100'],['기관 평가',f=>f.quality+'/100'],['응답 이력',f=>'응답률 '+f.responseRate+'% · 불일치 '+f.mismatchRate+'%'],['정맥 투여',f=>capability('정맥 투여',f.iv)],['격리 처치',f=>capability('격리 처치',f.isolation)],['수용 응답',f=>statusBadge(U.facilityStatus(f,state))],['기관 회신',f=>displayFact(f.response.reason)]].map(([k,fn])=>`<tr><th>${k}</th>${fs.map(f=>`<td>${fn(f)}</td>`).join('')}</tr>`).join('')}<tr><th>기관 선택</th>${fs.map(f=>`<td>${button('이 기관 선택','choose','primary small',`data-id="${f.id}"`)}</td>`).join('')}</tr></tbody></table></div><p class="tiny" style="margin-top:15px">기관 회신과 이동·비용 조건을 함께 비교해 주세요.</p>`);return;
    }
    if(a==='choose'){const f=M.facilities.find(f=>f.id===id);modal('선택한 기관 확인',`<h3>${f.name}</h3><p class="sub">${f.area} · 이동 ${f.minutes}분 · 예상 비용 ${money(f.cost)}/일</p><div class="notice">선택한 기관에만 회송 정보가 전달되도록 동의합니다. 다른 기관의 문의는 종료됩니다. 실제 전원·진료 확정은 아닙니다.</div><label class="check"><input type="checkbox" id="share-consent"><span>선택한 기관에 회송 정보를 제공하는 데 동의합니다.<small>범위: 가상 환자 식별명·필요 처치·회송서에 기재된 상세 처방. 목적: 전원 준비와 첫 진료 연계. 시연값은 이 브라우저에만 저장됩니다.</small></span></label>`,button('취소','close')+button('동의하고 기관 선택','confirm-choice','primary',`data-id="${id}"`));return;}
    if(a==='confirm-choice'){if(await act({type:'choose',id,consent:$('#share-consent').checked})){compare.clear();close();toast('기관 선택을 기록했습니다. 의뢰기관에서 전원을 준비합니다.');}return;}
    if(a==='supplement'){modal('담당의 보완 회신 입력 (시연)',`<p class="sub">문서에 없는 처방을 추정하지 않습니다. 이 입력은 담당의가 보완한 정보를 전달받는 상황을 시연합니다.</p>${M.missing(state).map(k=>`<label class="field"><span>${M.fields[k]}</span><input id="supp-${k}" value="" placeholder="담당의 보완 회신 내용 (가상)"></label>`).join('')}<label class="check"><input type="checkbox" id="doctor-replied"><span>담당의의 보완 회신을 받은 상황임을 확인합니다. (시연)</span></label>`,button('취소','close')+button('보완 회신 반영','confirm-supplement','primary'));return;}
    if(a==='confirm-supplement'){const values=Object.fromEntries(M.missing(state).map(k=>[k,$('#supp-'+k).value]));if(await act({type:'supplement',values,confirmed:$('#doctor-replied').checked})){close();toast('담당의 보완 회신을 반영했습니다.');}return;}
    if(a==='reset'){resetModal(state.scenario);return;}
    if(a==='confirm-reset'){if(working)return;generation++;autoRunId++;autoRunning=false;aiError='';agentError='';basicMode=false;sourceEditMode=false;consentDraft=false;state=M.initial($('#reset-scenario')?.value||el.dataset.scenario);compare.clear();role='hospital';facility='saebom';view='case';liveMessage='회송 정보 점검 대기';save();close();render();toast('가상 시나리오를 초기화했습니다.');return;}
    if(a==='export'){
      const data={prototype:'CareBridge v5',synthetic:true,scope:'비응급 회송 결정 이후부터 의뢰기관의 첫 진료 이행 회신 확인까지',scenario:state.scenario,stage:M.stages[state.stage],completed:state.ack,metrics:state.metrics,events:state.events,apiMode:apiReady,apiCalls};
      const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='carebridge-demo-record.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('가상 시연 기록을 내려받았습니다.');return;
    }
  }
  function resetModal(scenario){modal('시연 상태 초기화',`<p>현재 브라우저의 시연 진행 상태를 초기화하고, 선택한 가상 시나리오를 시작합니다.</p><label class="field"><span>시작할 시나리오</span><select id="reset-scenario"><option value="normal" ${scenario==='normal'?'selected':''}>정상 연계</option><option value="missing" ${scenario==='missing'?'selected':''}>회송 정보 누락</option><option value="unavailable" ${scenario==='unavailable'?'selected':''}>수용 불가·재탐색</option></select></label><p class="tiny">다른 파일이나 실제 데이터에는 영향을 주지 않습니다.</p>`,button('취소','close')+button('초기화하고 시작','confirm-reset','primary',`data-scenario="${scenario}"`));}
  async function checkApi(){
    try{if(location.protocol==='file:')throw Error('offline');const r=await fetch('/api/health',{signal:AbortSignal.timeout(3500)});const result=await r.json();apiReady=r.ok&&result.version===2;aiAvailable=apiReady&&result.aiAnalysisAvailable===true;}catch{apiReady=false;}
    apiChecked=true;liveMessage=state.stage===0?'회송 정보 점검 대기':'동의와 진행 상태 확인';render();kickAutomation();
  }
  function integrationModal(){
    modal('기능·시연 범위',`<div class="notice ${apiReady?'green':'amber'}">${apiReady?'서비스를 이용할 수 있습니다.':'기본 시연 모드입니다. AI 분석과 지도 조회는 웹사이트에서 이용해 주세요.'}</div>${dl([['AI 분석',aiAvailable?'회송서 항목 정리, 기관 추천 근거, 문의 초안 작성, 기관 회신 분석과 다음 작업 안내를 지원합니다.':'현재 AI 분석을 사용할 수 없습니다. 기본 항목 점검으로 진행할 수 있습니다.'],['기관 정보','공개 지도에서 기관의 기본 정보를 조회합니다. 실제 병상·처치 역량·수용 가능 여부는 제공하지 않습니다.'],['이동 경로','예시 위치를 기준으로 경로를 확인합니다. 환자 주소는 사용하지 않습니다.'],['기관 문의·회신','모의 응답으로 업무 흐름을 시연합니다. 실제 병원 연락·병상 예약은 하지 않습니다.'],['직접 확인할 작업','환자 동의·기관 선택, 서류·일정 확인, 첫 진료 회신, 의뢰기관 최종 확인'],['진행 상태 저장','현재 브라우저에 저장합니다. 기기 간 동기화와 실제 역할 인증은 제공하지 않습니다.']])}`,button('상태 다시 확인','retry-api')+button('닫기','close','primary'));
  }

  async function loadRoute(id){
    const target=$('#route-result');if(!target)return;target.innerHTML='<p role="status">이동 경로를 불러오고 있습니다…</p>';
    if(!apiReady){target.innerHTML='<p class="notice amber">이동 경로를 불러올 수 없습니다. 웹사이트에서 다시 확인해 주세요.</p>';return;}
    try{const started=performance.now(),r=await fetch('/api/route?facility='+encodeURIComponent(id),{signal:AbortSignal.timeout(8500)}),data=await r.json();apiCalls.unshift({action:'OSRM route',status:r.status,ms:Math.round(performance.now()-started),time:new Date().toISOString()});if(!r.ok)throw Error(data.error);routeResults[id]=data;if(!$('#route-result')||$('#route-result').dataset.id!==id)return;
      const coords=data.coordinates,xs=coords.map(c=>c[0]),ys=coords.map(c=>c[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
      const points=coords.map(c=>[24+(c[0]-minX)/(maxX-minX||1)*452,196-(c[1]-minY)/(maxY-minY||1)*172]);
      target.innerHTML=mapFrame(data.coordinates.at(-1)[1],data.coordinates.at(-1)[0],'가상 목적지의 실제 지도 위치')+`<div class="notice green"><b>${data.km}km · 약 ${data.minutes}분</b><br>지도에서 조회한 경로 · 예시 위치 기준 · 실시간 교통 미반영</div><svg viewBox="0 0 500 220" class="route-chart" role="img" aria-label="조회한 이동 경로"><polyline points="${points.map(c=>c.join(',')).join(' ')}" fill="none" stroke="#29357d" stroke-width="4" stroke-linejoin="round"/><circle cx="${points[0][0]}" cy="${points[0][1]}" r="6" fill="#19765f"/><circle cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" r="6" fill="#29357d"/></svg><p class="tiny">© OpenStreetMap contributors / OSRM · 위 지도는 가상 목적지, 선은 조회한 이동 경로입니다.<br>실제 병원 위치·환자 주소가 아닌 가상 출발지와 목적지입니다. 카드의 고정 시연 거리·정렬에는 반영하지 않습니다.</p>`;
    }catch(e){if($('#route-result')?.dataset.id===id)target.innerHTML=`<p class="notice amber">${esc(e.message||'이동 경로를 불러오지 못했습니다.')} 카드의 고정 시연값을 실제 조회 결과로 대신 표시하지 않습니다.</p>`;}
  }
  function mapFrame(lat,lon,title){return `<iframe class="map-frame" title="${esc(title)}" loading="lazy" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=${lon-.025}%2C${lat-.016}%2C${lon+.025}%2C${lat+.016}&layer=mapnik&marker=${lat}%2C${lon}"></iframe>`;}
  function hospitalsPage(){
    const names={gwanak:'서울 관악·서초',dongjak:'서울 동작·영등포',anyang:'경기 안양'},data=hospitalResults,focus=hospitalFocus||data?.center;
    return pageHead('실제 의료기관 검색','공개 지도에서 의료기관 기본 정보를 조회합니다. 시연용 수용 문의와는 별도 화면입니다.')+`<section class="panel"><div class="directory-toolbar"><label class="field"><span>검색 지역 · 주변 지도 영역</span><select id="hospital-area">${Object.entries(names).map(([k,v])=>`<option value="${k}" ${k===hospitalArea?'selected':''}>${v}</option>`).join('')}</select></label>${button(hospitalLoading?'공개 정보 조회 중…':'공개 기관 정보 조회','hospital-search','primary',hospitalLoading?'disabled':'')}</div><p class="tiny">실제 기관명·위치: OpenStreetMap / Nominatim 공개 정보 · 병상, 현재 수용 여부, 처치 역량은 제공하지 않습니다.</p>${hospitalError?`<div class="notice amber" role="alert">${esc(hospitalError)}</div>`:''}${hospitalLoading?'<div class="pending" role="status">공개 지도에서 기관 정보를 불러오고 있습니다…</div>':''}${data?`<div class="row">${badge('기관 정보 조회 완료','green')}${badge(data.items.length+'개 기관')}<span class="tiny">조회 ${when(data.at)}${data.cached?' · 최근 조회 결과 재사용':''}</span></div>`:''}</section>${data?`<div class="directory-layout"><div class="directory-list">${data.items.length?data.items.map(f=>`<article class="panel directory-item"><span class="tiny">공개 지도 등록 기관</span><h2>${esc(f.name)}</h2><p class="sub">${esc(f.address||'주소 상세 미등록 · 지도에서 위치를 확인해 주세요.')}</p>${f.phone?`<p class="tiny">등록 전화 ${esc(f.phone)}</p>`:''}<div class="row">${button('지도에서 보기','hospital-map','small',`data-id="${esc(f.id)}"`)}<a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">원본 정보 ↗</a>${f.website?`<a href="${esc(f.website)}" target="_blank" rel="noopener noreferrer">등록 홈페이지 ↗</a>`:''}</div></article>`).join(''):'<section class="panel">이 지역에서 등록 정보를 찾지 못했습니다. 다른 지역을 선택해 주세요.</section>'}</div><section class="panel directory-map"><h2>${esc(focus.name||names[data.area]+' 검색 중심')}</h2>${mapFrame(focus.lat,focus.lon,'실제 기관 검색 지역 지도')}<p class="tiny">© OpenStreetMap contributors · 지도와 기관 정보의 최신성·완전성을 보장하지 않습니다. <a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noopener noreferrer">지도 이용 정책</a> · 소규모 시연용, 6시간 캐시·연속 호출 제한 적용.</p><div class="notice">여기에 표시된 실제 기관에 문의·예약을 전송하지 않습니다. 회송 시연은 별도의 가상 기관으로 진행합니다.</div></section></div>`:''}`;
  }
  async function loadHospitals(){
    if(hospitalLoading)return;hospitalArea=$('#hospital-area')?.value||hospitalArea;hospitalLoading=true;hospitalError='';hospitalResults=null;hospitalFocus=null;render();
    try{const start=performance.now(),r=await fetch('/api/hospitals?area='+hospitalArea,{signal:AbortSignal.timeout(20000)}),data=await r.json();apiCalls.unshift({action:'공개 의료기관 검색',status:r.status,ms:Math.round(performance.now()-start),time:new Date().toISOString()});if(!r.ok)throw Error(data.error);hospitalResults=data;}
    catch(e){hospitalError=e.message||'기관 정보를 불러오지 못했습니다.';}finally{hospitalLoading=false;if(view==='hospitals')render();}
  }
  function enhance(){
    const footer=$('.app-footer');if(footer)footer.textContent='서울대학교 산업공학과 · 헬스케어 서비스 혁신 프로젝트 / CareBridge v5 · 시연용';
    const strip=$('.demo-strip span:last-child');if(strip)strip.textContent=apiReady?'수용 응답은 모의 데이터':'기본 시연 모드 · 수용 응답은 모의 데이터';
    const next=$('.walkthrough');if(next&&nextRole()!==role&&!next.querySelector('[data-action="next-role"]'))next.insertAdjacentHTML('beforeend',button(roles[nextRole()]+' 화면으로','next-role','small'));
    if(next&&autoEnabled&&(state.stage===1&&state.consent||state.stage===2)&&!allAnsweredWithoutAcceptance()){next.querySelector('span').textContent='기관 문의와 회신을 확인하고 있어요. 환자 선택과 최종 확인은 직접 진행합니다.';next.querySelector('[data-action="next-role"]')?.remove();}
    if(next&&allAnsweredWithoutAcceptance())next.querySelector('span').textContent='수용 가능한 기관이 없습니다. 의뢰기관에서 추가 정보 요청 또는 탐색 범위를 확인해 주세요.';
    if(view==='case'){
      if(role==='facility'&&state.inquiryNotes?.[facility]&&!$('#inquiry-note-summary')){$('.grid > div:first-child .panel')?.insertAdjacentHTML('beforeend',`<section id="inquiry-note-summary" class="notice"><h3>의뢰기관의 보완 회신</h3><p>${esc(state.inquiryNotes[facility])}</p><small>담당의 확인 내용 전달 · 가상 시연</small></section>`);}
      if(role==='hospital'&&!$('.automation-panel')){$('.grid > div:last-child')?.insertAdjacentHTML('afterbegin',connectionPanel());}
      if(role==='hospital'&&state.stage===2&&state.inquiries.some(id=>!state.responses[id])&&!$('[data-action="timeout-demo"]'))$('.grid > div:last-child .panel')?.insertAdjacentHTML('beforeend',button('무응답 예외 시연','timeout-demo','quiet small'));
      if(role==='hospital'&&state.stage===2&&!Object.keys(state.responses).length&&!$('[data-action="expand"]')){$('.grid > div:last-child .panel:nth-child(2)')?.insertAdjacentHTML('beforeend',button('무응답 시 범위 조정·재문의','expand','small'));}
      if(role==='patient'&&state.stage<3&&!$('.automation-panel')){$('.empty-hint')?.insertAdjacentHTML('afterbegin',connectionPanel());}
      if(role==='patient'&&allAnsweredWithoutAcceptance()){const title=$('.empty-hint > h2');if(title)title.textContent='담당자가 수용 조건을 다시 확인해야 해요.';const sub=$('.empty-hint > p');if(sub)sub.textContent='현재 문의 기관 중 수용이 확인된 곳이 없습니다. 의뢰기관에서 추가 정보 요청이나 이동 범위를 확인한 뒤 다시 안내합니다.';}
      if(state.stage>=1&&state.stage<=3){
        for(const card of document.querySelectorAll('.facility')){const name=card.querySelector('h3')?.textContent,f=M.facilities.find(x=>x.name===name);if(f&&!card.querySelector('.facility-photo'))card.insertAdjacentHTML('afterbegin',photo(f));}
      }
      for(const card of document.querySelectorAll('.facility')){
        const name=card.querySelector('h3')?.textContent,f=M.facilities.find(x=>x.name===name);
        if(f&&state.responses[f.id]?.status==='more'&&role==='hospital'&&state.stage===2&&!card.querySelector('[data-action="more-info"]'))card.querySelector('.facility-bottom .row')?.insertAdjacentHTML('beforeend',button('추가 정보 회신','more-info','small',`data-id="${f.id}"`));
      }
      const value=$('.case-summary > div:nth-child(2) .value');if(value)value.textContent=state.data.treatment||'회송서 점검 전';
      if(state.stage===1&&!state.consent){const live=$('.automation-live');if(live)live.innerHTML='<span class="connection-dot"></span>환자 동의 대기 · 문의 생성을 보류하고 있습니다.';}
      if(state.stage===6&&state.visit?.result==='missed'){const live=$('.automation-live');if(live)live.innerHTML='<span class="connection-dot"></span>첫 진료 미이행 · 담당자의 사유 확인과 재연계 필요';}
      if(state.stage===7){const old=$('.complete h1');if(old){const h=document.createElement('h2');h.textContent=old.textContent;old.replaceWith(h);}}
    }
    if(view==='guide'){$('.readme').innerHTML=`<h2>3분 시연 순서</h2><ol><li>의뢰기관: 담당의 결정 확인 → 정보 구조화 → 기관 문의 준비</li><li>환자·보호자: 희망 조건 선택 → 비식별 기관 문의 동의 확인 → 동의하고 기관 찾기</li><li>자동 진행: 문의 생성 → 기관별 모의 수용 응답 → 수용 확인 후보 공개</li><li>환자·보호자: 사진·거리·비용·기관 회신 비교 → 기관 선택과 별도 정보 제공 동의</li><li>의뢰기관: 서류·이동 일정·환자 안내 확인 → 전달 기록 생성</li><li>수용기관: 첫 진료 이행 또는 미이행 회신</li><li>의뢰기관: 이행 회신 확인 후 완료. 미이행은 재연계.</li></ol><h2>AI가 도와주는 업무</h2><p>회송서의 항목을 정리하고, 환자 조건에 맞는 기관의 추천 근거와 문의 초안을 작성합니다. 기관 회신을 분석해 다음 작업을 안내합니다. 처치 가능 여부나 수용 결정은 의료진·기관이 판단하고, 기관은 환자·보호자가 선택합니다.</p><p>환자의 거리·비용·방문 시간 조건은 후보 탐색에 반영됩니다. 기관 정보·평가·응답 이력·등록 병상은 예시값입니다. 기관이 등록 정보를 변경하거나 환자가 후보를 거절하면 탐색 조건을 다시 확인하고 문의 동의를 받습니다.</p><p>공개 지도에서 실제 의료기관의 기본 정보와 예시 위치의 이동 경로를 조회할 수 있습니다. 회송 시연의 기관 문의·수용 응답은 모의 데이터이며, 실제 병원 연락·병상 예약·문자 전송은 하지 않습니다.</p><h2>예외 경로</h2><p>정보 누락: 담당의 보완 회신 전 진행 차단. 수용 불가: 40km로 범위 확장 후 동의 재확인. 무응답: 자동 진행을 끄고 담당자가 범위 조정. 추가 정보 요청: 자동 진행을 끈 뒤 기관의 요청에 담당의 확인 내용을 회신. 첫 진료 미이행: 완료 차단 후 재연계.</p><h2>저장과 사진</h2><p>상태는 현재 브라우저에만 저장합니다. 서버는 저장·기기 간 동기화·의료용 역할 인증을 하지 않습니다. 내려받은 HTML을 직접 열면 서버 기능 없이 브라우저 모드로 동작합니다.</p><p>각 기관의 시설 사진은 서로 다른 AI 생성 예시이며 실제 기관의 시설이나 품질을 나타내지 않습니다. 기관·거리·금액·처방도 모두 시연값입니다.</p>${button('기능·시연 범위 보기','integration','primary')}`;}
    const dialog=$('#dialog');if(dialog.open&&dialog.querySelector('h2')?.textContent&&M.facilities.some(f=>f.name===dialog.querySelector('h2').textContent)&&!dialog.querySelector('.facility-photo')){
      const f=M.facilities.find(f=>f.name===dialog.querySelector('h2').textContent);dialog.querySelector('.dialog-body').insertAdjacentHTML('afterbegin',photo(f));dialog.querySelector('.dialog-body').insertAdjacentHTML('beforeend',`<h3>이동 경로 참고</h3><p class="tiny">공개 지도에서 이동 경로 확인 · 예시 위치 기준</p>${button('이동 경로 확인','route','',`data-id="${f.id}"`)}<div id="route-result" data-id="${f.id}"></div>`);
    }
  }
  function replyQuote(text,status){
    const expressions={accepted:/수용이 가능합니다|수용 가능합니다|수용 가능|희망 일정 수용/g,rejected:/수용할 수 없습니다|수용 불가|수용이 불가|수용할 수 없음/g,more:/보완이 필요합니다|보완이 필요|정보 보완|판단 전|아직 수용 가능 응답이 아닙니다/g,timeout:/응답 기한|확인하지 못했습니다/g};
    const pattern=expressions[status];if(!pattern)return esc(text);let out='',from=0;
    for(const match of String(text).matchAll(pattern)){out+=esc(String(text).slice(from,match.index))+`<mark class="reply-emphasis">${esc(match[0])}</mark>`;from=match.index+match[0].length;}
    return out+esc(String(text).slice(from));
  }
  function agentDetail(){
    const a=state.lastAgent;if(!a){toast('문의 동의 후 AI 분석이 진행됩니다.');return;}
    const replies=a.interpretations||[],count=status=>replies.filter(r=>r.status===status).length,n=count('accepted'),tone=n?'green':!replies.length?'pending':count('rejected')===replies.length?'red':'amber';
    const title=n?`수용 가능한 기관 ${n}곳을 확인했습니다.`:count('more')?'추가 정보를 확인해야 수용 여부를 판단할 수 있습니다.':count('timeout')?'기관의 수용 응답을 확인하지 못했습니다.':replies.length?'현재 수용 가능한 기관이 없습니다.':'기관의 수용 응답을 기다립니다.';
    const summary=`<section class="reply-overview overview-${tone}" aria-label="회신 분석 요약"><strong>${esc(title)}</strong><div class="row">${['accepted','rejected','more','timeout'].filter(status=>count(status)).map(status=>statusBadge({...U.responsePresentation(status),label:U.responsePresentation(status).label+' '+count(status)+'곳'})).join('')}</div><p>다음 작업: <b>${esc(a.actionLabel)}</b></p></section>`;
    modal('AI 추천·문의·회신 근거',`<p class="tiny">${when(a.at)} AI 분석${a.cached?' · 검증 결과 재사용':''}</p>${summary}<h3>환자 희망 조건</h3><p>${esc(M.profile(state).text)}</p>${a.recommendations.length?`<h3>매칭 점수와 AI 추천 근거</h3><p class="tiny">처치·거리·비용 상한을 검사한 뒤 다기준 점수로 정렬합니다. 점수는 임상적 적합성 평가가 아닙니다.</p>${a.recommendations.map(r=>`<section class="agent-evidence"><div class="row space"><h3>${esc(M.facilities.find(f=>f.id===r.id).name)}</h3><span class="evidence-score">조건 적합 점수 <b>${r.score}</b>/100</span></div><ul>${r.basis.map(x=>`<li>${displayFact(x)}</li>`).join('')}</ul></section>`).join('')}`:''}<h3>비식별 문의 초안</h3><div class="tagged-referral inquiry-highlight" aria-label="문의 초안 핵심 항목">${highlightedText(state.inquiryDraft||'문의 초안 작성 전',true)}</div><h3>기관 회신 분석</h3>${replies.length?replies.map(r=>{const presentation=U.responsePresentation(r.status);return `<article class="reply-card reply-${presentation.tone}" aria-label="${esc(M.facilities.find(f=>f.id===r.id).name+' '+presentation.label)}"><div class="reply-card-head"><h4>${esc(M.facilities.find(f=>f.id===r.id).name)}</h4>${statusBadge(presentation)}</div><p class="reply-quote">${replyQuote(r.quote,r.status)}</p><p class="reply-next">${esc(presentation.hint)}</p></article>`;}).join(''):'<p class="tiny">기관 응답을 받은 뒤 원문 근거와 해석을 보여줍니다.</p>'}<details class="agent-history"><summary>최근 AI 작업 기록</summary><ol>${(state.agentRuns||[]).map(r=>`<li>${when(r.at)} · ${esc(r.action)}</li>`).join('')}</ol></details><p class="tiny">실제 병원 연락·예약은 하지 않습니다. 기관 문의·회신은 모의 데이터이며 수용 결정·환자 선택·최종 확인은 별도 단계입니다.</p>`,button('닫기','close')+button(state.stage===3?'후보 비교·선택으로':'다음 작업 확인','agent-workflow','primary'));
  }
  function renderTaskPanel(){
    if(view!=='case')return;
    const t=U.nextTask(state,role,{canAI:aiAvailable&&state.source===M.initial(state.scenario).source,missing:M.missing(state).map(k=>M.fields[k]),auto:autoEnabled,consentDraft,facility,agentError,noCandidates:!M.candidates(state).some(f=>f.eligible),acceptedCount:M.accepted(state).length,compareCount:compare.size});
    const primary=state.stage===3&&role==='patient'&&compare.size<2?'':'primary';
    const markup=`<section class="task-panel task-${t.tone}" aria-labelledby="task-title"><div><div class="task-kicker">${state.stage+1} / ${M.stages.length} · ${esc(t.owner)}</div><h2 id="task-title" tabindex="-1">${esc(t.title)}</h2><p>${esc(t.description)}</p></div><div class="task-action">${t.action?button(esc(t.label)+' <span aria-hidden="true">→</span>',t.action,primary, t.id?`data-id="${esc(t.id)}"`:''):'<span class="task-wait" role="status"><span class="connection-dot on"></span>자동 진행 중</span>'}</div></section>`;
    const old=$('.task-panel');if(old)old.outerHTML=markup;else $('.page-heading')?.insertAdjacentHTML('afterend',markup);
  }
  function updateFormReadiness(){
    if(working)return;
    const gate=(action,ok)=>{document.querySelectorAll(`[data-action="${action}"]`).forEach(b=>b.disabled=!ok);};
    const formTask=(action,ready)=>{const b=$('.task-panel button');if(!b)return;b.dataset.action=ready?action:'focus-'+action;b.disabled=false;b.innerHTML=(action==='response'?(ready?'수용 응답 보내기':'수용 여부 입력하기'):(ready?'첫 진료 회신 보내기':'이행 여부 입력하기'))+' <span aria-hidden="true">→</span>';};
    if($('#share-consent'))gate('confirm-choice',$('#share-consent').checked);
    if($('#doctor-replied'))gate('confirm-supplement',$('#doctor-replied').checked&&M.missing(state).every(k=>$('#supp-'+k)?.value.trim()));
    if($('#inquiry-attest'))gate('send-info',$('#inquiry-attest').checked&&!!$('#inquiry-note')?.value.trim());
    if(state.stage===0){gate('parse',state.doctorApproved);gate('ai-parse',state.doctorApproved&&apiReady&&aiAvailable&&state.source===M.initial(state.scenario).source);}
    if(state.stage===4)gate('handoff',Object.values(state.prep).every(Boolean));
    if($('#response-status')){const value=$('#response-status').value,required=['more','rejected'].includes(value);$('#response-reason').setAttribute('aria-required',String(required));$('#response-reason').closest('label').querySelector('span').textContent=value==='rejected'?'수용 불가 사유 (필수)':value==='more'?'추가 정보 요청 내용 (필수)':'수용 조건 또는 참고 사항 (선택)';const ready=['accepted','more','rejected'].includes(value)&&(!required||!!$('#response-reason').value.trim());gate('response',ready);formTask('response',ready);}
    if($('#visit-result')){const value=$('#visit-result').value,required=value==='missed';$('#visit-note').setAttribute('aria-required',String(required));$('#visit-note').closest('label').querySelector('span').textContent=required?'미이행 사유 (필수)':'추가 확인 사항 (선택)';const ready=['done','missed'].includes(value)&&(!required||!!$('#visit-note').value.trim());gate('visit',ready);formTask('visit',ready);}
  }
  function enhanceUX(){
    const header=document.querySelector('header');
    if(header&&!$('.mobile-nav'))header.insertAdjacentHTML('afterend',`<nav class="mobile-nav" aria-label="모바일 작업 메뉴">${button('회송 업무','case',view==='case'?'active':'')}${button('처리 기록','history',view==='history'?'active':'')}${button('공개 기관 정보','hospitals',view==='hospitals'?'active':'')}${button('시연 안내','guide',view==='guide'?'active':'')}</nav>`);
    if(view==='case'){
      document.querySelectorAll('#main button.primary').forEach(b=>{if(!(state.stage===3&&role==='patient'&&b.dataset.action==='choose'))b.classList.remove('primary');});
      renderTaskPanel();
      if(role==='patient'&&state.stage===3&&M.accepted(state).length>1&&compare.size){const fs=M.accepted(state).filter(f=>compare.has(f.id));$('.patient-layout')?.insertAdjacentHTML('beforeend',`<section class="compare-tray" aria-label="비교에 담은 기관"><div><b>${fs.length}개 기관을 담았어요</b><div class="compare-chips">${fs.map(f=>button(esc(f.name)+' ×','compare','quiet small',`data-id="${f.id}" aria-label="${esc(f.name)} 비교에서 제외"`)).join('')}</div></div><div class="row">${button('비우기','clear-compare','quiet small')}${button('담은 기관 비교하기','open-compare','primary',fs.length<2?'disabled':'')}</div>${fs.length<2?'<p class="tiny">비교할 기관을 한 곳 더 담아 주세요.</p>':''}</section>`);}
      if(role==='hospital'&&(state.stage===1||state.stage===2))$('.toolbar')?.insertAdjacentHTML('afterend',`<div class="status-key" aria-label="기관 상태 안내">${statusBadge({label:'가능',tone:'green',icon:'✓'})}${statusBadge({label:'불가',tone:'red',icon:'×'})}${statusBadge({label:'확인 전·추가 확인',tone:'amber',icon:'!'})}<span>처치 역량과 현재 수용 응답은 구분해 확인합니다.</span></div>`);
    }
    updateFormReadiness();
  }
  document.addEventListener('input',updateFormReadiness);
  document.addEventListener('change',updateFormReadiness);
  document.addEventListener('click',dispatch);
  document.addEventListener('input',e=>{if(e.target.id==='referral-source'&&state.stage===0){state.source=e.target.value;state.parsed=false;state.data={};state.extraction=null;const aiButton=$('[data-action="ai-parse"]');if(aiButton)aiButton.disabled=state.source!==M.initial(state.scenario).source||!apiReady||!aiAvailable;$('[data-action="ready"]')?.closest('.footer-action')?.remove();const panel=[...document.querySelectorAll('.panel')].find(p=>p.querySelector('h2')?.textContent==='구조화된 회송 정보');if(panel)panel.innerHTML='<h2>구조화된 회송 정보</h2><p class="notice amber">문서가 수정되었습니다. 회송 정보를 다시 구조화해 주세요.</p>';save();const highlight=$('#referral-highlight');if(highlight)highlight.innerHTML=highlightedSource();renderTaskPanel();updateFormReadiness();}});
  document.addEventListener('change',async e=>{
    const t=e.target;
    if(t.id==='scenario-select'){resetModal(t.value);return;}
    if(t.id==='facility-select'){facility=t.value;render();return;}
    if(t.id==='referral-source'){return;}
    if(t.dataset.change==='attest')await act({type:'attest',value:t.checked});
    if(t.dataset.change==='consent-draft'){consentDraft=t.checked;render();$('[data-change="consent-draft"]')?.focus({preventScroll:true});return;}
    if(t.dataset.change==='consent'){if(!t.checked){compare.clear();consentDraft=false;}await act({type:'consent',value:t.checked});}
    if(t.dataset.change?.startsWith('prep-'))await act({type:'prep',key:t.dataset.change.slice(5),value:t.checked});
  });
  render();
  checkApi();
})();
